using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;
using RAGGit.Core.Abstractions;
using RAGGit.Core.Abstractions.Repositories;
using RAGGit.Core.Models;

namespace RAGGit.Retrieval;

/// <summary>
/// Composes one transient document from a description (034). It retrieves
/// relevant library chunks through the existing policy and never writes query
/// history, library records, or generated bytes.
/// </summary>
public sealed class DocumentCreationPipeline
{
    private readonly RetrievalService _retrievalService;
    private readonly GenerationService _generationService;
    private readonly IDocumentRepository _documents;
    private readonly ILogger<DocumentCreationPipeline> _logger;

    public DocumentCreationPipeline(
        RetrievalService retrievalService,
        GenerationService generationService,
        IDocumentRepository documents,
        ILogger<DocumentCreationPipeline>? logger = null
    )
    {
        ArgumentNullException.ThrowIfNull(retrievalService);
        ArgumentNullException.ThrowIfNull(generationService);
        ArgumentNullException.ThrowIfNull(documents);

        _retrievalService = retrievalService;
        _generationService = generationService;
        _documents = documents;
        _logger = logger ?? NullLogger<DocumentCreationPipeline>.Instance;
    }

    public async Task<DocumentDraft> CreateAsync(
        DocumentCreationRequest request,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(request);

        if (!request.TryGetFormat(out var format))
        {
            throw new ArgumentException("Unsupported document format.", nameof(request));
        }

        var chunks = await _retrievalService.RetrieveAsync(
            request.Description,
            _retrievalService.DefaultTopK,
            cancellationToken
        );
        var documentNames = await ResolveDocumentNamesAsync(chunks, cancellationToken);

        var (body, citationIds) = await _generationService.GenerateDocumentAsync(
            request.Description,
            format,
            chunks,
            documentNames,
            cancellationToken
        );

        var sources = chunks
            .Where(chunk => citationIds.Contains(chunk.ChunkId))
            .Where(chunk => Guid.TryParse(chunk.DocumentId, out _))
            .Select(chunk => new Citation
            {
                DocumentId = Guid.Parse(chunk.DocumentId),
                DocumentName = documentNames.GetValueOrDefault(chunk.DocumentId),
                ChunkId = chunk.ChunkId,
                Text = chunk.Text,
                Ordinal = chunk.Ordinal,
            })
            .ToList();

        _logger.LogInformation(
            "Document creation composed {SourceCount} sources from {ChunkCount} retrieved chunks",
            sources.Select(source => source.DocumentId).Distinct().Count(),
            chunks.Count
        );

        return new DocumentDraft
        {
            Description = request.Description,
            Body = body,
            Sources = sources,
        };
    }

    private async Task<Dictionary<string, string?>> ResolveDocumentNamesAsync(
        IReadOnlyList<SearchResult> chunks,
        CancellationToken cancellationToken
    )
    {
        var names = new Dictionary<string, string?>(StringComparer.Ordinal);
        foreach (var documentId in chunks.Select(chunk => chunk.DocumentId).Distinct())
        {
            if (!Guid.TryParse(documentId, out var id))
            {
                continue;
            }

            try
            {
                var document = await _documents.FindByIdAsync(id, cancellationToken);
                names[documentId] = document?.Filename;
            }
            catch (Exception exception)
            {
                _logger.LogDebug(
                    exception,
                    "Document name lookup failed for {DocumentId}",
                    documentId
                );
            }
        }

        return names;
    }
}
